window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-30b134bf854beb48"]={"versions": [{"id": "FIG-30b134bf854beb48", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Classic Platform (id LinNm). Es stellt die statischen Modulabhängigkeiten und Schnittstellenbeziehungen des LIN-Netzwerkmanagements (LinNm) innerhalb des Kommunikationsstapels sowie zu Diagnose-/Fehlerbehandlungsmodulen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei BSW-Komponenten:</p>\n<ul class=\"fig-list\">\n<li><strong>LinNm</strong> (LIN Network Management): Zentrale Komponente. Stellt Schnittstellen mit dem Präfix <code>LinNm_*</code> bereit (Socket/Ball-Verbindung Richtung Nm), nutzt eine unbenannte Callback-/Notification-Schnittstelle von Nm und nutzt die Funktion <code>Det_ReportError</code> des DET.</li>\n<li><strong>Nm</strong> (Generic Network Management Interface): Übergeordnete Komponente, greift über <code>LinNm_*</code> auf LinNm zu und stellt eine Callback-Schnittstelle für LinNm bereit.</li>\n<li><strong>DET</strong> (Default Error Tracer): Service-Komponente, stellt die Schnittstelle <code>Det_ReportError</code> zur Erfassung von Entwicklungsfehlern für LinNm bereit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Asynchroner und synchroner Funktionsaufruf-Ablauf über C-APIs:</p>\n<ul class=\"fig-list\">\n<li>Das generische Netzwerkmanagement (<code>Nm</code>) initiiert Steuerungs- und Abfragebefehle an <code>LinNm</code> über die API-Gruppe <code>LinNm_*</code>.</li>\n<li><code>LinNm</code> meldet Zustandsänderungen oder Ereignisse über Callbacks an <code>Nm</code> zurück.</li>\n<li>Tritt innerhalb von <code>LinNm</code> bei aktivierter Fehlererkennung ein Entwicklungs- oder Konfigurationsfehler auf, ruft <code>LinNm</code> synchron die Schnittstelle <code>Det_ReportError</code> des Moduls <code>DET</code> auf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für die Implementierung des Moduls LIN Network Management:</p>\n<ul class=\"fig-list\">\n<li>Das Modul LinNm muss die in der AUTOSAR-SWS spezifizierten <code>LinNm_*</code>-APIs implementieren und für das Nm-Interface exportieren.</li>\n<li>Bei aktiviertem Development Error Detection (<code>LINNM_DEV_ERROR_DETECT == STD_ON</code>) ist die Einbindung des Moduls DET und der Aufruf von <code>Det_ReportError</code> obligatorisch.</li>\n<li>Die Interaktion mit Nm erfordert die Einhaltung der standardisierten Funktionssignaturen und Rückruffunktionen gemäß Spezifikation.</li>\n</ul>"}, {"id": "FIG-3fc00caeda984952", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm im Kontext der AUTOSAR Classic Platform (id LinNm). Es stellt die statischen Modulabhängigkeiten und Schnittstellenbeziehungen des LIN-Netzwerkmanagements (LinNm) innerhalb des Kommunikationsstapels sowie zu Diagnose-/Fehlerbehandlungsmodulen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei BSW-Komponenten:</p>\n<ul class=\"fig-list\">\n<li><strong>LinNm</strong> (LIN Network Management): Zentrale Komponente. Stellt Schnittstellen mit dem Präfix <code>LinNm_*</code> bereit (Socket/Ball-Verbindung Richtung Nm), nutzt eine unbenannte Callback-/Notification-Schnittstelle von Nm und nutzt die Funktion <code>Det_ReportError</code> des DET.</li>\n<li><strong>Nm</strong> (Generic Network Management Interface): Übergeordnete Komponente, greift über <code>LinNm_*</code> auf LinNm zu und stellt eine Callback-Schnittstelle für LinNm bereit.</li>\n<li><strong>DET</strong> (Default Error Tracer): Service-Komponente, stellt die Schnittstelle <code>Det_ReportError</code> zur Erfassung von Entwicklungsfehlern für LinNm bereit.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Asynchroner und synchroner Funktionsaufruf-Ablauf über C-APIs:</p>\n<ul class=\"fig-list\">\n<li>Das generische Netzwerkmanagement (<code>Nm</code>) initiiert Steuerungs- und Abfragebefehle an <code>LinNm</code> über die API-Gruppe <code>LinNm_*</code>.</li>\n<li><code>LinNm</code> meldet Zustandsänderungen oder Ereignisse über Callbacks an <code>Nm</code> zurück.</li>\n<li>Tritt innerhalb von <code>LinNm</code> bei aktivierter Fehlererkennung ein Entwicklungs- oder Konfigurationsfehler auf, ruft <code>LinNm</code> synchron die Schnittstelle <code>Det_ReportError</code> des Moduls <code>DET</code> auf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für die Implementierung des Moduls LIN Network Management:</p>\n<ul class=\"fig-list\">\n<li>Das Modul LinNm muss die in der AUTOSAR-SWS spezifizierten <code>LinNm_*</code>-APIs implementieren und für das Nm-Interface exportieren.</li>\n<li>Bei aktiviertem Development Error Detection (<code>LINNM_DEV_ERROR_DETECT == STD_ON</code>) ist die Einbindung des Moduls DET und der Aufruf von <code>Det_ReportError</code> obligatorisch.</li>\n<li>Die Interaktion mit Nm erfordert die Einhaltung der standardisierten Funktionssignaturen und Rückruffunktionen gemäß Spezifikation.</li>\n</ul>"}], "trans": [{"from": "FIG-30b134bf854beb48", "to": "FIG-3fc00caeda984952", "fr": "R4.0.3", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
